begin;
create function public.commercial_config(p_org uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
begin if not private.company_can_manage(p_org) then raise exception 'commercial_access_denied' using errcode='42501';end if;
 return jsonb_build_object('settings',coalesce((select to_jsonb(s) from public.commercial_settings s where organization_id=p_org),jsonb_build_object('revision',1,'enabled',false,'interval_minutes',null,'max_attempts',null,'contact_hours',null,'after_limit','stop','conversion_criterion','booking','eligible_types',array['first_contact','quote_followup','abandoned','approval_followup','requested_return'],'loss_reasons',array['price','deadline','availability','location','withdrawal','competitor','no_response','not_offered','invalid_contact','other'])),
 'rules',coalesce((select jsonb_agg(to_jsonb(r) order by created_at) from public.commercial_rules r where organization_id=p_org),'[]'::jsonb),'services',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name)) from public.services where organization_id=p_org and active),'[]'::jsonb),'effective',private.commercial_effective(p_org,null,null));end;$$;
create function public.commercial_config_save(p_org uuid,p_revision integer,p_data jsonb) returns void language plpgsql security definer set search_path='' as $$
declare s public.commercial_settings;begin perform private.company_lock(p_org);perform private.company_keys(p_data,array['enabled','interval_minutes','max_attempts','eligible_types','contact_hours','after_limit','conversion_criterion','loss_reasons']);insert into public.commercial_settings(organization_id) values(p_org) on conflict do nothing;select * into s from public.commercial_settings where organization_id=p_org;
 if p_revision is distinct from s.revision then raise exception 'commercial_revision_conflict' using errcode='40001';end if;select * into s from jsonb_populate_record(s,p_data);
 if exists(select 1 from unnest(s.loss_reasons) x where x !~ '^[a-z][a-z0-9_]{0,79}$') or(select count(distinct x) from unnest(s.loss_reasons)x)<>cardinality(s.loss_reasons) then raise exception 'invalid_loss_reasons' using errcode='22023';end if;
 update public.commercial_settings set enabled=s.enabled,interval_minutes=s.interval_minutes,max_attempts=s.max_attempts,eligible_types=s.eligible_types,contact_hours=s.contact_hours,after_limit=s.after_limit,conversion_criterion=s.conversion_criterion,loss_reasons=s.loss_reasons,revision=revision+1 where organization_id=p_org;
 if not s.enabled then perform private.commercial_cancel_tasks(id,'recovery_disabled') from public.opportunities where organization_id=p_org;end if;end;$$;
create function public.commercial_rule_save(p_org uuid,p_id uuid,p_revision integer,p_data jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare s public.commercial_rules;begin perform private.company_lock(p_org);perform private.company_keys(p_data,array['service_id','kind','enabled','interval_minutes','max_attempts']);
 if p_id is null then if coalesce(p_revision,0)<>0 then raise exception 'commercial_revision_conflict' using errcode='40001';end if;
 insert into public.commercial_rules(organization_id,service_id,kind,enabled,interval_minutes,max_attempts) values(p_org,(p_data->>'service_id')::uuid,p_data->>'kind',coalesce((p_data->>'enabled')::boolean,true),(p_data->>'interval_minutes')::int,(p_data->>'max_attempts')::int) returning id into p_id;
 else select * into s from public.commercial_rules where id=p_id and organization_id=p_org;if s.id is null then raise exception 'commercial_access_denied' using errcode='42501';end if;if s.revision is distinct from p_revision then raise exception 'commercial_revision_conflict' using errcode='40001';end if;select * into s from jsonb_populate_record(s,p_data);
 update public.commercial_rules set service_id=s.service_id,kind=s.kind,enabled=s.enabled,interval_minutes=s.interval_minutes,max_attempts=s.max_attempts,revision=revision+1 where id=p_id;end if;return p_id;end;$$;
create function public.commercial_refresh(p_org uuid default null,p_after uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare o record;n int=0;cursor_id uuid;begin perform private.central_lock();if p_org is not null and not private.central_staff(p_org) then raise exception 'commercial_access_denied' using errcode='42501';end if;
 for o in select id from private.commercial_op where private.central_staff(organization_id) and(p_org is null or organization_id=p_org) and(p_after is null or id>p_after) and not private.commercial_terminal(commercial_state) order by id limit 200 loop perform private.commercial_sync(o.id);n=n+1;cursor_id=o.id;end loop;return jsonb_build_object('processed',n,'next',case when n=200 then cursor_id end);end;$$;
create function public.commercial_context(p_code text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare o private.commercial_op;q public.quote_requests;tk text;cfg jsonb;begin select * into o from private.commercial_op where commercial_code=p_code;if o.id is null or not private.central_staff(o.organization_id) then raise exception 'commercial_access_denied' using errcode='42501';end if;
 select * into q from public.quote_requests where opportunity_id=o.id order by created_at desc limit 1;select public_code into tk from public.tickets where request_id=q.id order by created_at desc limit 1;cfg=private.commercial_effective(o.organization_id,o.service_id,case when q.state='quoted' then 'quote_followup' when q.state='draft' then 'abandoned' when q.state='approved' then 'approval_followup' else 'first_contact' end);
 return jsonb_build_object('code',p_code,'organization_id',o.organization_id,'company',(select name from public.organizations where id=o.organization_id),'timezone',(select timezone from public.organizations where id=o.organization_id),'state',o.commercial_state,'revision',o.commercial_revision,'criterion',coalesce(o.commercial_conversion_criterion,cfg->>'conversion_criterion'),'loss_reason',o.commercial_loss_reason,'converted_at',o.commercial_converted_at,'last_contact',o.commercial_last_contact_at,
 'customer',(select name from public.customers where id=o.customer_id),'contact',case when private.commercial_contact_ok(o.id) then(select whatsapp from public.customers where id=o.customer_id) end,'contact_allowed',private.commercial_contact_ok(o.id),'request',q.public_code,'request_state',q.state,'ticket',tk,'can_operate',private.commercial_can_operate(o.organization_id),'admin',private.company_can_manage(o.organization_id),'me',auth.uid(),'config',cfg,
 'service',coalesce((select x->>'name' from public.consumer_publications p cross join lateral jsonb_array_elements(p.payload->'services') x where p.id=q.publication_id and x->>'code'=q.service_code),'Serviço'),
 'source',coalesce((select source from public.opportunity_context where opportunity_id=o.id),'direct'),'value',(select total_cents from public.quote_versions where request_id=q.id order by version desc limit 1),
 'tasks',coalesce((select jsonb_agg(to_jsonb(t)||jsonb_build_object('assignee_name',(select display_name from public.profiles where id=t.assignee_id),'assignee_eligible',private.commercial_can_operate(o.organization_id,t.assignee_id)) order by t.created_at desc) from public.commercial_tasks t where opportunity_id=o.id),'[]'::jsonb),
 'events',coalesce((select jsonb_agg(jsonb_build_object('event',e.event,'state',e.state,'reason',e.reason,'at',e.created_at,'actor',p.display_name) order by e.event_sequence) from public.commercial_events e left join public.profiles p on p.id=e.actor_id where opportunity_id=o.id),'[]'::jsonb),
 'attempts',coalesce((select jsonb_agg(jsonb_build_object('outcome',a.outcome,'note',a.note,'next_due_at',a.next_due_at,'at',a.created_at,'actor',p.display_name) order by a.created_at) from public.commercial_attempts a join public.commercial_tasks t on t.id=a.task_id left join public.profiles p on p.id=a.actor_id where t.opportunity_id=o.id),'[]'::jsonb),
 'recipients',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.display_name)) from public.profiles p where private.commercial_can_operate(o.organization_id,p.id) and private.central_eligible(o.organization_id,p.id)),'[]'::jsonb),
 'loss_reasons',coalesce((select to_jsonb(loss_reasons) from public.commercial_settings where organization_id=o.organization_id),'[]'::jsonb));end;$$;
create function public.commercial_list(p_filters jsonb default '{}',p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;begin if not private.is_active_user() then raise exception 'commercial_access_denied' using errcode='42501';end if;perform private.company_keys(p_filters,array['org','search','state','source','owner','kind','date','view','loss_reason']);if length(coalesce(p_filters->>'search',''))>120 then raise exception 'invalid_search' using errcode='22023';end if;
 select coalesce(jsonb_agg(x order by x->>'due',x->>'code'),'[]'::jsonb) into result from(
 select jsonb_build_object('code',o.commercial_code,'organization_id',o.organization_id,'company',org.name,'customer',c.name,'service',coalesce((select x->>'name' from public.consumer_publications p cross join lateral jsonb_array_elements(p.payload->'services')x where p.id=q.publication_id and x->>'code'=q.service_code),'Serviço'),'source',coalesce(oc.source,'direct'),'state',o.commercial_state,'loss_reason',o.commercial_loss_reason,'value',(select total_cents from public.quote_versions where request_id=q.id order by version desc limit 1),'last_contact',o.commercial_last_contact_at,'due',t.due_at,'kind',t.kind,'attempt',t.attempt,'max_attempts',t.max_attempts,'owner',p.display_name,'task_state',t.state,'task',t.public_code,'overdue',t.due_at<now(),'timezone',org.timezone) x
 from private.commercial_op o join public.organizations org on org.id=o.organization_id join public.customers c on c.id=o.customer_id join public.quote_requests q on q.opportunity_id=o.id left join public.opportunity_context oc on oc.opportunity_id=o.id left join public.commercial_tasks t on t.opportunity_id=o.id and t.state not in ('completed','cancelled') left join public.profiles p on p.id=t.assignee_id
 where private.central_staff(o.organization_id)
 and(nullif(p_filters->>'org','') is null or o.organization_id=(p_filters->>'org')::uuid) and(nullif(p_filters->>'state','') is null or o.commercial_state=p_filters->>'state')
 and(nullif(p_filters->>'source','') is null or coalesce(oc.source,'direct')=p_filters->>'source') and(nullif(p_filters->>'owner','') is null or (p_filters->>'owner'='mine' and t.assignee_id=auth.uid()) or t.assignee_id::text=p_filters->>'owner')
 and(nullif(p_filters->>'kind','') is null or t.kind=p_filters->>'kind') and(nullif(p_filters->>'loss_reason','') is null or o.commercial_loss_reason=p_filters->>'loss_reason') and(nullif(p_filters->>'date','') is null or (o.created_at at time zone org.timezone)::date=(p_filters->>'date')::date)
 and(coalesce(p_filters->>'search','')='' or concat_ws(' ',c.name,org.name,o.commercial_code,(select x->>'name' from public.consumer_publications pub cross join lateral jsonb_array_elements(pub.payload->'services')x where pub.id=q.publication_id and x->>'code'=q.service_code),p.display_name) ilike '%'||(p_filters->>'search')||'%')
 and(coalesce(p_filters->>'view','all')='all' or(p_filters->>'view'='today' and (t.due_at at time zone org.timezone)::date<=(now() at time zone org.timezone)::date) or(p_filters->>'view'='upcoming' and (t.due_at at time zone org.timezone)::date>(now() at time zone org.timezone)::date) or(p_filters->>'view'='finished' and private.commercial_terminal(o.commercial_state)) or(p_filters->>'view'='overdue' and t.due_at<now()) or(p_filters->>'view'='responded' and o.commercial_state='responded') or(p_filters->>'view'='abandoned' and t.kind='abandoned'))
 order by t.due_at nulls last,o.id limit 101 offset greatest(coalesce(p_offset,0),0)) rows;
 return jsonb_build_object('items',coalesce((select jsonb_agg(value) from jsonb_array_elements(result) with ordinality where ordinality<=100),'[]'::jsonb),'has_more',jsonb_array_length(result)>100,'organizations',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name,'admin',private.company_can_manage(id))) from public.organizations where private.central_staff(id)),'[]'::jsonb));end;$$;
create function public.commercial_op_act(p_code text,p_revision integer,p_action text,p_data jsonb,p_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare o private.commercial_op;prior jsonb;payload jsonb;res jsonb;due timestamptz;
begin perform private.central_lock();select * into o from private.commercial_op where commercial_code=p_code;if o.id is null or not private.commercial_can_operate(o.organization_id) then raise exception 'commercial_access_denied' using errcode='42501';end if;
 payload=jsonb_build_array(p_code,p_revision,p_action,p_data);prior=private.consumer_idem(o.organization_id,'commercial_op',p_key,payload);if prior is not null then return prior;end if;
 if o.commercial_revision is distinct from p_revision then raise exception 'commercial_revision_conflict' using errcode='40001';end if;if private.commercial_terminal(o.commercial_state) then raise exception 'commercial_closed' using errcode='22023';end if;
 if not private.company_can_manage(o.organization_id) and exists(select 1 from public.commercial_tasks where opportunity_id=o.id and state not in ('completed','cancelled') and assignee_id is not null and assignee_id<>auth.uid() and private.commercial_can_operate(o.organization_id,assignee_id)) then raise exception 'commercial_owner_required' using errcode='42501';end if;
 if p_action='lose' then perform private.company_keys(p_data,array['reason']);if not exists(select 1 from public.commercial_settings where organization_id=o.organization_id and p_data->>'reason'=any(loss_reasons)) then raise exception 'invalid_loss_reason' using errcode='22023';end if;perform private.commercial_stop(o.id,'lost',p_data->>'reason');
 elsif p_action='schedule' then perform private.company_keys(p_data,array['due_at']);due=(p_data->>'due_at')::timestamptz;if due is null or due<now() or due>now()+interval '365 days' then raise exception 'invalid_due' using errcode='22023';end if;perform private.commercial_cancel_tasks(o.id,'manual_reschedule');if private.commercial_sync(o.id,due,'requested_return') is null then raise exception 'commercial_not_eligible' using errcode='42501';end if;update public.commercial_opportunity_state set commercial_revision=commercial_revision+1 where id=o.id;
 else raise exception 'unknown_action' using errcode='22023';end if;res=jsonb_build_object('code',p_code,'ok',true);perform private.consumer_remember(o.organization_id,'commercial_op',p_key,payload,res);return res;end;$$;
create function public.commercial_task_act(p_code text,p_revision integer,p_action text,p_data jsonb,p_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare t public.commercial_tasks;o private.commercial_op;q public.quote_requests;cfg jsonb;prior jsonb;payload jsonb;res jsonb;target uuid;outcome text;reason text;due timestamptz;
begin perform private.central_lock();select * into t from public.commercial_tasks where public_code=p_code;if t.id is null or not private.commercial_can_operate(t.organization_id) then raise exception 'commercial_access_denied' using errcode='42501';end if;
 if p_action<>'claim' and t.assignee_id is distinct from auth.uid() and not private.company_can_manage(t.organization_id) then raise exception 'commercial_owner_required' using errcode='42501';end if;
 payload=jsonb_build_array(p_code,p_revision,p_action,p_data);prior=private.consumer_idem(t.organization_id,'commercial_task',p_key,payload);if prior is not null then return prior;end if;if t.revision is distinct from p_revision then raise exception 'commercial_revision_conflict' using errcode='40001';end if;
 select * into o from private.commercial_op where id=t.opportunity_id;select * into q from public.quote_requests where id=t.request_id;cfg=private.commercial_effective(t.organization_id,o.service_id,t.kind);
 if t.state in ('completed','cancelled') or private.commercial_terminal(o.commercial_state) then raise exception 'commercial_closed' using errcode='22023';end if;
 if not private.commercial_contact_ok(o.id) or not(cfg->>'enabled')::boolean or not(cfg->'eligible_types' ? t.kind) or t.attempt>least(t.max_attempts,(cfg->>'max_attempts')::int) or t.cycle<>o.commercial_cycle or(q.state='quoted' and exists(select 1 from public.quote_versions where id=q.current_version_id and expires_at<=now())) then raise exception 'commercial_not_eligible' using errcode='42501';end if;
 case p_action
 when 'claim' then perform private.company_keys(p_data,array[]::text[]);if t.assignee_id is not null and t.assignee_id<>auth.uid() and private.commercial_can_operate(t.organization_id,t.assignee_id) then raise exception 'commercial_already_assigned' using errcode='40001';end if;
 if not private.company_can_manage(t.organization_id) and not exists(select 1 from public.work_sessions where user_id=auth.uid() and ended_at is null and presence in ('available','busy')) then raise exception 'presence_required' using errcode='42501';end if;update public.commercial_tasks set assignee_id=auth.uid(),state='assigned' where id=t.id;perform private.commercial_event(o.id,'assigned',t.id);
 when 'transfer' then perform private.company_keys(p_data,array['user_id']);target=(p_data->>'user_id')::uuid;if not private.commercial_can_operate(t.organization_id,target) or not private.central_eligible(t.organization_id,target) then raise exception 'commercial_invalid_recipient' using errcode='42501';end if;update public.commercial_tasks set assignee_id=target,state='assigned' where id=t.id;perform private.commercial_event(o.id,'transferred',t.id,target::text);
 when 'start' then perform private.company_keys(p_data,array[]::text[]);if t.due_at>now() or private.commercial_window(t.organization_id,now()) is distinct from now() then raise exception 'commercial_outside_window' using errcode='22023';end if;update public.commercial_tasks set state='in_progress',assignee_id=coalesce(assignee_id,auth.uid()) where id=t.id;perform private.commercial_event(o.id,'started',t.id);
 when 'priority' then perform private.company_keys(p_data,array['priority']);update public.commercial_tasks set priority=(p_data->>'priority')::int where id=t.id;perform private.commercial_event(o.id,'rescheduled',t.id,'priority_changed');
 when 'reschedule' then perform private.company_keys(p_data,array['due_at']);due=(p_data->>'due_at')::timestamptz;if due is null or due<now() or due>now()+interval '365 days' then raise exception 'invalid_due' using errcode='22023';end if;due=private.commercial_window(t.organization_id,due);if due is null then raise exception 'no_contact_window' using errcode='22023';end if;update public.commercial_tasks set due_at=due,state='rescheduled' where id=t.id;perform private.commercial_event(o.id,'rescheduled',t.id,'operator');
 when 'cancel' then perform private.company_keys(p_data,array[]::text[]);perform private.commercial_stop(o.id,'no_response','operator_stopped');
 when 'result' then perform private.company_keys(p_data,array['outcome','note','next_due_at']);outcome=p_data->>'outcome';if t.state<>'in_progress' or t.due_at>now() or private.commercial_window(t.organization_id,now()) is distinct from now() then raise exception 'commercial_outside_window' using errcode='22023';end if;
 if outcome='approved' and q.state<>'approved' then raise exception 'real_approval_required' using errcode='23514';end if;if outcome='booked' and not exists(select 1 from public.appointments where request_id=q.id and state='confirmed') then raise exception 'real_booking_required' using errcode='23514';end if;
 due=case when outcome='return_later' then (p_data->>'next_due_at')::timestamptz else now()+make_interval(mins=>(t.rule_snapshot->>'interval_minutes')::int) end;if outcome='return_later' and (due is null or due<=now() or due>now()+interval '365 days') then raise exception 'invalid_due' using errcode='22023';end if;
 insert into public.commercial_attempts(organization_id,task_id,actor_id,outcome,note,next_due_at) values(t.organization_id,t.id,auth.uid(),outcome,coalesce(p_data->>'note',''),case when outcome='return_later' then due end);update public.commercial_tasks set state='completed',result=outcome,completed_at=clock_timestamp() where id=t.id;
 update public.commercial_opportunity_state set commercial_last_contact_at=clock_timestamp(),commercial_revision=commercial_revision+1 where id=o.id;perform private.commercial_event(o.id,'attempt',t.id,outcome);perform private.commercial_event(o.id,'completed',t.id,outcome);
 reason=case outcome when 'price' then 'price' when 'competitor' then 'competitor' when 'lost_interest' then 'withdrawal' when 'not_needed' then 'not_offered' when 'invalid_contact' then 'invalid_contact' end;
 if outcome='refused' then perform private.commercial_stop(o.id,'refused','customer_refused');elsif reason is not null then perform private.commercial_stop(o.id,case when outcome='invalid_contact' then 'ineligible' else 'lost' end,reason);
 elsif outcome in ('responded','interested','approved','booked','other') then update public.commercial_opportunity_state set commercial_state='responded',commercial_changed_at=clock_timestamp() where id=o.id;perform private.commercial_event(o.id,'responded',t.id,outcome);
 else if t.attempt>=least(t.max_attempts,(cfg->>'max_attempts')::int) then perform private.commercial_stop(o.id,case when t.rule_snapshot->>'after_limit'='lose' then 'lost' else 'no_response' end,'no_response');else update public.commercial_opportunity_state set commercial_state='negotiating',commercial_changed_at=clock_timestamp() where id=o.id;perform private.commercial_sync(o.id,due,case when outcome='return_later' then 'requested_return' else t.kind end);end if;end if;
 else raise exception 'unknown_action' using errcode='22023';end case;
 update public.commercial_tasks set revision=revision+1 where id=t.id;res=jsonb_build_object('code',p_code,'ok',true);perform private.consumer_remember(t.organization_id,'commercial_task',p_key,payload,res);return res;end;$$;
do $$ declare r record;begin for r in select p.oid::regprocedure s,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname like 'commercial_%' loop execute format('revoke all on function %s from public,anon,authenticated',r.s);if r.nspname='public' then execute format('grant execute on function %s to authenticated',r.s);end if;end loop;end;$$;
commit;
